export const PASSAGES = [{"id":"pl-k-01","pool":"placement-k","title":"The Red Hen","genre":"narrative","source":"app-original","license":"app-original","text":"Pam has a red hen. The hen sits in a box. It is a big box. The hen gets up. Look! The hen has an egg. Pam pets the hen. The hen is a good hen.","questions":[{"type":"literal","q":"Who has a red hen?","options":["Pam","Ben","Kim"],"answer":0,"evidence":"Pam has a red hen."},{"type":"literal","q":"Where does the hen sit?","options":["in a box","on a bed","in a cup"],"answer":0,"evidence":"The hen sits in a box."},{"type":"sequence","q":"What does the hen have when it gets up?","options":["an egg","a hat","a bug"],"answer":0,"evidence":"The hen has an egg."}],"grade":1,"words":36,"auto":{"fk":-2,"decodable":1,"checks":"pass"}},{"id":"pl-k-02","pool":"placement-k","title":"Ben and the Pup","genre":"narrative","source":"app-original","license":"app-original","text":"Ben has a tan pup. The pup can dig. It digs in the mud. Mud is on his legs! Ben gets a tub. The pup sits in the tub. Now the pup is not a mud pup. Ben hugs his pup.","questions":[{"type":"literal","q":"What can the pup do?","options":["dig","run","hop"],"answer":0,"evidence":"The pup can dig."},{"type":"sequence","q":"What does Ben get when the pup is muddy?","options":["a tub","a mop","a rug"],"answer":0,"evidence":"Ben gets a tub."},{"type":"literal","q":"Where does the pup sit?","options":["in the tub","in the mud","on the bed"],"answer":0,"evidence":"The pup sits in the tub."}],"grade":1,"words":41,"auto":{"fk":-1.8,"decodable":1,"checks":"pass"}},{"id":"pl-k-03","pool":"placement-k","title":"Kim and the Hat","genre":"narrative","source":"app-original","license":"app-original","text":"Kim has a red hat. Kim sets the hat on a log. A cat gets in the hat! Kim is sad. The cat naps and naps. At last, the cat gets up. Kim gets the hat. Kim pats the cat.","questions":[{"type":"literal","q":"Where does Kim set the hat?","options":["on a log","on a bed","in a box"],"answer":0,"evidence":"Kim sets the hat on a log."},{"type":"literal","q":"What gets in the hat?","options":["a cat","a pig","a dog"],"answer":0,"evidence":"A cat gets in the hat!"},{"type":"why","q":"Why is Kim sad?","options":["a cat is in her hat","her hat is wet","her hat has a rip"],"answer":0,"evidence":"A cat gets in the hat!"}],"grade":1,"words":40,"auto":{"fk":-1.8,"decodable":0.95,"checks":"pass"}},{"id":"pl-g1-01","pool":"placement-g1","title":"Jay and the Kite","genre":"narrative","source":"app-original","license":"app-original","text":"Jay has a new kite. It is red and green. Jay and Dad go up a big hill. The wind is strong today. Jay runs fast. The kite goes up, up, up! It flies high in the sky. Then the wind stops. The kite falls down into a tree. Jay is sad. Dad gets a long stick. He pokes the kite free. Jay smiles. \"Let us try again,\" said Dad.","questions":[{"type":"literal","q":"What colors is Jay's kite?","options":["red and green","blue and pink","black and gold"],"answer":0,"evidence":"It is red and green."},{"type":"sequence","q":"Where does the kite land when the wind stops?","options":["in a tree","in a lake","on a roof"],"answer":0,"evidence":"The kite falls down into a tree."},{"type":"why","q":"Why does the kite fall?","options":["the wind stops","Jay lets it go","the string breaks"],"answer":0,"evidence":"Then the wind stops."},{"type":"main","q":"What is the story mostly about?","options":["Jay flies a kite with Dad","Jay climbs a tall tree","Dad buys a new kite"],"answer":0}],"grade":1,"words":70,"auto":{"fk":-1.2,"decodable":1,"checks":"pass"}},{"id":"pl-g1-02","pool":"placement-g1","title":"Busy Bees","genre":"informational","source":"app-original","license":"app-original","text":"Bees are small bugs with six legs. Many bees live in a hive. A hive can be inside a tree. Bees fly from plant to plant. They sip a sweet drink from each blossom. Then they take it back to the hive. In the hive, bees make it into honey. Bees can sting, so keep your hands still. The bee may fly away. Bees help plants make seeds. We need bees!","caption":"A bee sits on a pink blossom.","questions":[{"type":"literal","q":"Where do many bees live?","options":["in a hive","in a pond","in a cave"],"answer":0,"evidence":"Many bees live in a hive."},{"type":"why","q":"Why do we need bees?","options":["they help plants make seeds","they help the rain to fall","they keep the bugs away"],"answer":0,"evidence":"Bees help plants make seeds."},{"type":"feature","q":"What does the caption show?","options":["a bee on a blossom","a bee in a hive","a bug on a leaf"],"answer":0},{"type":"main","q":"What is this mostly about?","options":["how bees live and help","how to plant a seed","why bugs have six legs"],"answer":0}],"grade":1,"words":71,"auto":{"fk":-0.3,"decodable":0.99,"checks":"pass"}},{"id":"pl-g1-03","pool":"placement-g1","title":"Gail and the Boat","genre":"narrative","source":"app-original","license":"app-original","text":"Gail has a little boat. Gail and Mom made it from a box and a stick. Gail and Mom go to the creek. Gail sets the boat on the water. It floats! Then the wind blows. The boat floats away from Gail. \"Oh no!\" said Gail. Mom runs on the bank. She holds out a long stick. She pulls the boat back to the bank. Gail hugs Mom. \"Next time, I will hold the string,\" said Gail.","questions":[{"type":"literal","q":"Where do Gail and Mom take the boat?","options":["to the creek","to the lake","to the beach"],"answer":0,"evidence":"Gail and Mom go to the creek."},{"type":"why","q":"Why does the boat float away?","options":["the wind blows","Gail pushes it","a duck tugs it"],"answer":0,"evidence":"Then the wind blows."},{"type":"sequence","q":"What does Mom do after she runs on the bank?","options":["holds out a long stick","jumps into the water","calls for help"],"answer":0,"evidence":"She holds out a long stick."},{"type":"vocab","q":"In the story, what does floats mean?","options":["stays on top of water","sinks to the bottom","flies in the air"],"answer":0,"evidence":"It floats!"}],"grade":1,"words":77,"auto":{"fk":-1.2,"decodable":1,"checks":"pass"}},{"id":"pl-g1-04","pool":"placement-g1","title":"Snow Day","genre":"narrative","source":"app-original","license":"app-original","text":"Snow falls all night. When Kim wakes up, the grass is white. Kim and Seth go out to play. They roll the snow into three big balls. They stack the balls up high. Now they have a snowman! Seth gets two sticks for hands. Kim finds a red hat. The snowman needs a nose. Seth gives it a green bean. Then the sun comes out. Drip, drip, drip! The snowman gets thin. \"We can make a new one next time,\" said Kim.","questions":[{"type":"sequence","q":"What happens first in the story?","options":["snow falls all night","the sun comes out","Kim finds a red hat"],"answer":0,"evidence":"Snow falls all night."},{"type":"literal","q":"What does Seth use for the nose?","options":["a green bean","a red hat","two sticks"],"answer":0,"evidence":"Seth gives it a green bean."},{"type":"why","q":"Why does the snowman get thin?","options":["the sun comes out","the wind blows","Kim takes the hat"],"answer":0,"evidence":"Then the sun comes out."},{"type":"evidence","q":"Which sentence tells you the snow is melting?","options":["Drip, drip, drip!","Kim finds a red hat.","They stack the balls up high."],"answer":0,"evidence":"Drip, drip, drip!"}],"grade":1,"words":82,"auto":{"fk":-0.9,"decodable":1,"checks":"pass"}},{"id":"pl-g2-01","pool":"placement-g2","title":"The Squirrel and the Rabbit","genre":"narrative","source":"app-original","license":"app-original","text":"Late in the fall, a busy squirrel named Pip gathered acorns. She hid them under the roots of a tall oak tree. Her friend Rabbit hopped past and grinned. \"Why are you working so hard?\" he asked. \"The sun is warm, and there is plenty of food.\" Pip kept digging and storing her acorns. Soon the first snow came. The ground turned white and hard, and Rabbit could not find a single green leaf. He shivered beside the oak tree, hungry and cold. Pip peeked out of her nest and saw him. She did not tease him. Instead, she shared her acorns and showed him where to dig for roots. The next fall, Rabbit gathered food early, right beside his friend. Lesson: Getting ready early helps you, and sharing helps everyone.","questions":[{"type":"why","q":"Why did Rabbit go hungry in the winter?","options":["he saved no food in fall","Pip took all of his food","he was too sleepy to eat"],"answer":0,"evidence":"The ground turned white and hard, and Rabbit could not find a single green leaf."},{"type":"sequence","q":"What did Pip do when she saw Rabbit in the snow?","options":["shared her acorns","laughed at him","hid in her nest"],"answer":0,"evidence":"Instead, she shared her acorns and showed him where to dig for roots."},{"type":"vocab","q":"In the story, what does gathered mean?","options":["collected","threw away","planted"],"answer":0,"evidence":"Late in the fall, a busy squirrel named Pip gathered acorns."},{"type":"main","q":"What lesson does the fable teach?","options":["Get ready early and share.","Rabbits are faster than squirrels.","Always sleep in the winter."],"answer":0}],"grade":2,"words":131,"auto":{"fk":2.2,"decodable":1,"checks":"pass"}},{"id":"pl-g2-02","pool":"placement-g2","title":"A Frog Grows Up","genre":"informational","source":"app-original","license":"app-original","text":"A frog does not start out looking like a frog. It begins as a tiny egg in a pond. A mother frog can lay hundreds of eggs in one soft, jelly clump. After one to three weeks, a tadpole wiggles out of each egg. A tadpole has a long tail and breathes with gills, the way a fish does. It swims around and nibbles tiny plants under the water. Little by little, the tadpole changes. Its back legs grow first, and then its front legs appear. Its tail gets shorter and shorter. Inside its body, lungs form so it can breathe air. After about three months, the young frog hops out onto land. Someday it may lay eggs of its own, and the cycle will begin again.","caption":"A tadpole with new back legs swims in a pond.","questions":[{"type":"feature","q":"What does the caption tell about the picture?","options":["a tadpole with back legs","a frog sitting on land","eggs in a jelly clump"],"answer":0},{"type":"sequence","q":"What grows first on a tadpole?","options":["back legs","its lungs","big eyes"],"answer":0,"evidence":"Its back legs grow first, and then its front legs appear."},{"type":"literal","q":"How does a tadpole breathe under water?","options":["with gills","with lungs","with its tail"],"answer":0,"evidence":"A tadpole has a long tail and breathes with gills, the way a fish does."},{"type":"main","q":"What is this mostly about?","options":["how a frog grows up","how fish swim in ponds","what frogs like to eat"],"answer":0}],"grade":2,"words":127,"auto":{"fk":3.5,"decodable":1,"checks":"pass"}},{"id":"pl-g2-03","pool":"placement-g2","title":"The Missing Library Book","genre":"narrative","source":"app-original","license":"app-original","text":"Rosa's library book was due on Friday, but on Thursday night she could not find it anywhere. She searched under her bed and behind the couch. She even checked inside the refrigerator, because once she had left her lunchbox there. Her little brother, Mateo, followed her from room to room. \"Is it red with a dragon on the cover?\" he asked. Rosa spun around. \"Yes! Have you seen it?\" Mateo nodded and led her to the dog's basket. There was the book, tucked under a blanket beside a sleepy puppy named Pickles. \"I was reading him a bedtime story,\" Mateo explained. Rosa giggled and hugged him. The next morning, she returned the book on time, and she promised to read Mateo a story every night.","questions":[{"type":"literal","q":"Where did Rosa find the book?","options":["in the dog's basket","under her bed","behind the couch"],"answer":0,"evidence":"Mateo nodded and led her to the dog's basket."},{"type":"why","q":"Why did Rosa look in the refrigerator?","options":["she once left her lunch there","she wanted a snack after school","her mom told her to look there"],"answer":0,"evidence":"She even checked inside the refrigerator, because once she had left her lunchbox there."},{"type":"vocab","q":"In the story, what does due mean?","options":["must be returned","is very heavy","is lost"],"answer":0,"evidence":"Rosa's library book was due on Friday, but on Thursday night she could not find it anywhere."},{"type":"sequence","q":"What did Rosa do the next morning?","options":["returned the book on time","read a story to Pickles","searched behind the couch"],"answer":0,"evidence":"The next morning, she returned the book on time, and she promised to read Mateo a story every night."}],"grade":2,"words":125,"auto":{"fk":4,"decodable":0.98,"checks":"pass"}},{"id":"pl-g2-04","pool":"placement-g2","title":"Fall Colors","genre":"informational","source":"app-original","license":"app-original","text":"Leaves are green in summer because they hold a green coloring. This coloring helps them make food from sunlight. In the fall, the days get shorter and cooler. Many trees stop making food and get ready to rest for the winter. As the green coloring fades, other colors that were hiding in the leaf begin to show. Yellow and orange were there all summer long! Some leaves also make new red and purple colors in the fall. Later, the leaves turn brown, dry up, and drop to the ground. The tree is not sick. It is saving water and energy until spring, when new green leaves will grow.","caption":"Red, orange, and yellow maple leaves in the fall.","questions":[{"type":"why","q":"Why are leaves green in the summer?","options":["they hold a green coloring","they drink lots of rainwater","they are painted by the sun"],"answer":0,"evidence":"Leaves are green in summer because they hold a green coloring."},{"type":"sequence","q":"What happens to leaves after they turn brown?","options":["they dry up and drop","they turn green again","they grow bigger"],"answer":0,"evidence":"Later, the leaves turn brown, dry up, and drop to the ground."},{"type":"evidence","q":"Which sentence tells you that yellow was in the leaf all along?","options":["Yellow and orange were there all summer long!","Some leaves also make new red and purple colors in the fall.","The tree is not sick."],"answer":0,"evidence":"Yellow and orange were there all summer long!"},{"type":"feature","q":"What does the caption tell you?","options":["leaves on a maple in fall","green leaves in the spring","a bare tree in the snow"],"answer":0}],"grade":2,"words":108,"auto":{"fk":3.8,"decodable":0.99,"checks":"pass"}},{"id":"pl-listen-01","pool":"placement-listen","title":"Saturday Pancakes","genre":"narrative","source":"app-original","license":"app-original","text":"Every Saturday, Nia and her grandpa make pancakes together. Grandpa cracks the eggs, and Nia stirs the batter with a big wooden spoon. This Saturday, Grandpa opened the fridge and frowned. \"Oh dear, we are out of milk,\" he said. Nia had an idea. She knocked on the door next door, where Miss Lee lived. Miss Lee smiled and handed Nia a carton of milk. Soon the kitchen smelled sweet and buttery. Nia carried a warm stack of pancakes back to Miss Lee to say thank you. \"Now that is a good neighbor,\" Grandpa said with a wink.","questions":[{"type":"literal","q":"What were Nia and Grandpa out of?","options":["milk","eggs","butter"],"answer":0,"evidence":"\"Oh dear, we are out of milk,\" he said."},{"type":"sequence","q":"What did Nia do after Grandpa found no milk?","options":["knocked on Miss Lee's door","stirred the pancake batter","called the store for milk"],"answer":0,"evidence":"She knocked on the door next door, where Miss Lee lived."},{"type":"vocab","q":"What does neighbor mean in this story?","options":["a person who lives close by","a cook who makes breakfast","a spoon for stirring batter"],"answer":0,"evidence":"She knocked on the door next door, where Miss Lee lived."},{"type":"why","q":"Why did Nia bring pancakes to Miss Lee?","options":["to say thank you","to sell them","to get more eggs"],"answer":0,"evidence":"Nia carried a warm stack of pancakes back to Miss Lee to say thank you."}],"grade":1,"words":98,"auto":{"fk":2.9,"decodable":null,"checks":"pass"}},{"id":"pl-listen-02","pool":"placement-listen","title":"How Penguins Stay Warm","genre":"informational","source":"app-original","license":"app-original","text":"Emperor penguins live in Antarctica. It is one of the coldest places on Earth. The wind can howl, and the air is colder than a freezer. So how do these birds stay warm? First, a thick layer of blubber under their skin works like a cozy blanket. Next, their short feathers are packed close together. They keep out wind and water. On the coldest days, hundreds of penguins huddle in a big group. They take turns in the warm middle, so everyone gets a chance to warm up. A penguin dad even keeps his egg warm on top of his feet!","caption":"Emperor penguins huddle close together on the ice.","questions":[{"type":"main","q":"What is this mostly about?","options":["how penguins stay warm","how penguins catch fish","where penguins build nests"],"answer":0},{"type":"literal","q":"What works like a blanket for a penguin?","options":["a layer of blubber","a pile of soft snow","a nest of grass"],"answer":0,"evidence":"First, a thick layer of blubber under their skin works like a cozy blanket."},{"type":"why","q":"Why do penguins take turns in the middle?","options":["so everyone gets warm","to find more food","to hide from birds"],"answer":0,"evidence":"They take turns in the warm middle, so everyone gets a chance to warm up."},{"type":"literal","q":"Where does a penguin dad keep his egg?","options":["on top of his feet","inside a deep hole","under a big rock"],"answer":0,"evidence":"A penguin dad even keeps his egg warm on top of his feet!"}],"grade":1,"words":101,"auto":{"fk":3.3,"decodable":null,"checks":"pass"}},{"id":"pl-listen-03","pool":"placement-listen","title":"The Missing Mitten","genre":"narrative","source":"app-original","license":"app-original","text":"On the first snowy day of winter, Leo could only find one blue mitten. He looked in his coat pockets, under the bench by the door, and even inside his boots. No mitten. \"We will be late for the bus,\" Mom called. Just then, Leo heard giggling from the living room. His little sister, June, was sitting behind the sofa. The blue mitten was on her hand, and she had drawn a silly face on it with a marker. \"It's a puppet!\" she said proudly. Leo smiled. He gave June his old red sock for a new puppet, and he wore both mittens to school.","questions":[{"type":"literal","q":"What was Leo looking for?","options":["his blue mitten","his red sock","his school bus"],"answer":0,"evidence":"On the first snowy day of winter, Leo could only find one blue mitten."},{"type":"sequence","q":"What did Leo hear after Mom called?","options":["giggling","a barking dog","the bus horn"],"answer":0,"evidence":"Just then, Leo heard giggling from the living room."},{"type":"why","q":"Why was the mitten on June's hand?","options":["she made it a puppet","her hands were cold","she was going outside"],"answer":0,"evidence":"\"It's a puppet!\""},{"type":"vocab","q":"What does proudly mean in this story?","options":["pleased with what she made","worried she was in trouble","sleepy and ready for bed"],"answer":0,"evidence":"\"It's a puppet!\""}],"grade":1,"words":105,"auto":{"fk":2.5,"decodable":null,"checks":"pass"}},{"id":"pl-g10-01","pool":"placement-g10","title":"The Sound That Cancels Sound","genre":"informational","source":"app-original","license":"app-original","text":"On a long flight, the engines produce a steady roar that most passengers eventually stop noticing, even though it leaves them tired. Noise-cancelling headphones can make much of that roar seem to vanish. They do not work only by blocking sound more tightly, although their padding helps. Instead, they fight sound with sound.\n\nSound travels as a wave of pressure. As a speaker cone or a jet engine vibrates, it squeezes the air together and then lets it spread apart, creating alternating regions of high and low pressure that ripple outward to our ears. When two sound waves meet, their pressures add together. If the high points of one wave line up with the high points of another, the sound grows louder. But if the high points of one wave line up with the low points of another, the two can cancel each other out. Physicists call this destructive interference.\n\nActive noise-cancelling headphones put this principle to work. Tiny microphones on the outside, and often on the inside, of each ear cup constantly sample the surrounding noise. A small processor analyzes the incoming wave and generates a mirror image of it, an \"anti-noise\" signal whose pressure rises exactly when the noise falls. When the anti-noise reaches the ear together with the original noise, the two largely cancel, and the listener hears much less of the roar.\n\nThe timing must be remarkably precise. Sound moves about a foot in a thousandth of a second, so the electronics must respond almost instantly, adjusting continuously as the noise changes. This is why the technology works best on steady, low-pitched sounds such as engine hum, air conditioners and train rumble. Sudden, high-pitched sounds, such as a baby's cry or a clattering dish, change too quickly to cancel completely, so headphones rely on their padding to muffle them.\n\nThe idea is older than many people expect. A German physicist, Paul Lueg, patented the basic concept in the 1930s, and early systems were developed for pilots, who needed to hear spoken messages over loud engines. Only after electronics became small and inexpensive did the technology move into ordinary headphones. Today the same principle is used in some cars to reduce road noise, a reminder that sometimes the best way to create silence is to add more sound.","questions":[{"type":"main","q":"What is the main idea of the passage?","options":["Headphones reduce noise mainly through thick ear padding","Headphones reduce noise by producing an opposing sound wave","Headphones work best against sudden, high-pitched sounds"],"answer":1},{"type":"vocab","q":"In paragraph 3, what does 'sample' mean?","options":["taste or try out","play loudly through","measure small parts of"],"answer":2,"evidence":"Tiny microphones on the outside, and often on the inside, of each ear cup constantly sample the surrounding noise."},{"type":"why","q":"Why does the technology handle engine hum better than a baby's cry?","options":["Low, steady waves are easier to predict and cancel","Cries are much quieter than the sound of engines","Microphones cannot pick up sounds made by people"],"answer":0},{"type":"literal","q":"For whom were early noise-cancelling systems developed?","options":["drivers","pilots","musicians"],"answer":1,"evidence":"A German physicist, Paul Lueg, patented the basic concept in the 1930s, and early systems were developed for pilots, who needed to hear spoken messages over loud engines."}],"grade":10,"words":387,"auto":{"fk":8.8,"decodable":null,"checks":"pass"}},{"id":"pl-g10-02","pool":"placement-g10","title":"The Recording","genre":"narrative","source":"app-original","license":"app-original","text":"Abena had interviewed her grandfather for exactly eleven minutes before she realized she was asking the wrong questions.\n\nThe assignment for her history class was straightforward: record an oral history with an older relative and connect it to a major event of the twentieth century. She had arrived at his apartment with a list of questions typed on her phone, asking when he had left Ghana, why he had come to Toronto, and what the hardest part of moving had been. Her grandfather answered each one politely and briefly, the way he answered questions at the doctor's office, and the recording app showed a long, flat line between his short replies.\n\n\"Nineteen seventy-one, for work, and the cold,\" he said, as though he were reading items from a receipt.\n\nShe glanced at the next question, and then, without quite deciding to, she set the phone face down on the table. \"Grandpa,\" she said, \"what did your mother cook on the day you left?\"\n\nHe looked at her for a long moment, as if she had spoken in a language he had not heard in years. Then he laughed, a deep, startled sound, and leaned back in his chair. \"Groundnut soup,\" he said. \"With rice balls. She made far too much, because she said a man traveling so far should never go hungry, and I was not hungry at all, because I was frightened. I ate two bowls anyway, so she would not worry.\"\n\nFor the next hour he talked. He described the airport in Accra, the stiff new suit his uncle had lent him, and the shock of seeing his own breath in the air for the first time. He told her about the woman at the employment office who had mispronounced his name every week for a year, and about the day she finally said it correctly, and how he had nearly cried over something so small. Abena did not interrupt, and the phone lay face down, still recording; when she finally turned it over, the flat line on the screen had become a dense mountain range of sound.\n\nWhen she stopped the recording, her grandfather was quiet. \"Nobody ever asked me about the soup,\" he said.\n\nThat night, writing her report, Abena deleted most of the introduction she had planned. The textbook could explain the economics of migration. What she had recorded was something the textbook could never hold: the weight of a single bowl of soup, eaten to comfort a mother on a morning that changed everything.","questions":[{"type":"inference","q":"Why does Abena most likely set the phone face down?","options":["She wants to stop recording the whole interview","Her grandfather asks her to put the phone away","She senses her questions are keeping him distant"],"answer":2},{"type":"literal","q":"What did the grandfather's mother cook on the day he left?","options":["Rice and beans","Groundnut soup","Fried plantains"],"answer":1,"evidence":"\"Groundnut soup,\" he said."},{"type":"craft","q":"What does the change from 'a long, flat line' to 'a dense mountain range of sound' show?","options":["The interview became rich and full of detail","The phone's recording app stopped working","Her grandfather began to speak more loudly"],"answer":0},{"type":"theme","q":"Which idea about history does the passage suggest?","options":["Textbooks are usually wrong about migration","Older people prefer to avoid discussing the past","Personal details can reveal what textbooks miss"],"answer":2}],"grade":10,"words":421,"auto":{"fk":8.1,"decodable":null,"checks":"pass"}},{"id":"pl-g10-03","pool":"placement-g10","title":"In Defense of Boredom","genre":"argument","source":"app-original","license":"app-original","text":"Few experiences are as universally disliked as boredom. We reach for our phones in elevators, at red lights, and in the thirty seconds while a microwave runs, as if a moment without stimulation were a small emergency. Yet there are good reasons to believe that boredom is not a problem to be eliminated but a signal worth listening to, and that teenagers in particular would benefit from experiencing more of it.\n\nConsider how strongly people resist it. In a widely discussed 2014 study at the University of Virginia, researchers asked participants to sit alone in a room with their thoughts for up to fifteen minutes. The only possible distraction was a button that delivered a mild electric shock. Two-thirds of the men and about a quarter of the women chose to shock themselves rather than sit quietly. If adults would accept pain to avoid a quarter hour of their own company, it is worth asking what we lose by never practicing it.\n\nOne possible loss is creativity. Psychologists have found that when people perform a dull task before a creative one, such as copying numbers from a phone book, they often generate more original ideas afterward. A wandering mind makes unexpected connections. The background hum of constant entertainment may crowd out exactly the kind of drifting thought from which new ideas emerge.\n\nBoredom also carries information. It tells us that what we are doing does not match what we need, and it pushes us to seek something better: a new project, a conversation, a walk outside. When every flicker of boredom is immediately silenced with a video or a feed, we never learn what that discomfort was trying to say.\n\nCritics might reply that boredom is hardly a virtue, and they are partly right. Chronic boredom, the kind that comes from long periods without meaning or purpose, has been linked to poor mental health and risky behavior. No one should romanticize a life of empty days. But the argument here concerns ordinary, temporary boredom, the restless half hour on a quiet afternoon, not the crushing kind.\n\nParents, schools, and teenagers themselves could protect a little space for it: a commute without headphones, an evening without a screen, a weekend with nothing scheduled. It may feel uncomfortable at first. That discomfort is the point. A mind that has learned to sit with itself is better prepared to discover what it actually wants to do.","questions":[{"type":"claim","q":"What is the author's main claim?","options":["Ordinary boredom is useful and worth allowing","Teenagers should give up their phones forever","Chronic boredom improves mental health"],"answer":0},{"type":"claim","q":"How does the author respond to critics who say boredom is harmful?","options":["By arguing that chronic boredom is very rare","By claiming that risky behavior can be healthy","By separating brief boredom from chronic boredom"],"answer":2},{"type":"literal","q":"In the 2014 study, what was the only possible distraction?","options":["A phone loaded with games","A mild electric shock button","A window onto a garden"],"answer":1,"evidence":"The only possible distraction was a button that delivered a mild electric shock."},{"type":"why","q":"Why does the author describe the study about copying numbers?","options":["To show dull tasks can spark creativity","To prove phone books are still useful","To argue that copying improves memory"],"answer":0}],"grade":10,"words":404,"auto":{"fk":9.7,"decodable":null,"checks":"pass"}},{"id":"pl-g11-01","pool":"placement-g11","title":"The Archive in the Ice","genre":"informational","source":"app-original","license":"app-original","text":"Two miles beneath the surface of the Antarctic ice sheet lies one of the most remarkable archives on Earth. It contains no paper, no ink and no handwriting, yet it preserves a continuous record of the planet's atmosphere stretching back roughly eight hundred thousand years. Scientists read this archive by drilling cylinders of ice, called cores, and analyzing the air trapped inside them.\n\nThe process begins with snow. In the interior of Antarctica, so little melting occurs that each year's snowfall is buried beneath the next, gradually compressing under its own accumulating weight. As the snow becomes dense ice, tiny pockets of air are sealed between the grains, forming bubbles that function as miniature time capsules. A bubble from deep within a core contains a sample of the atmosphere as it existed when that layer was buried.\n\nDuring the early 2000s, a European project known as EPICA drilled more than three kilometers into the ice at a site called Dome C. The resulting core allowed researchers to measure carbon dioxide concentrations across eight glacial cycles, the long alternations between ice ages and warmer periods. The pattern they discovered was strikingly consistent: carbon dioxide rose during warm periods and fell during cold ones, but throughout the entire record it never exceeded about three hundred parts per million.\n\nThat ceiling gives today's measurements their significance. Atmospheric carbon dioxide has now risen above four hundred and twenty parts per million, a level unmatched anywhere in the ice-core record. The increase has occurred within roughly two centuries, an instant compared with the slow natural fluctuations preserved in the ice, and it coincides with the industrial burning of coal, oil and gas.\n\nIce cores reveal more than carbon dioxide. Layers of volcanic ash identify ancient eruptions, and variations in the chemistry of the water itself allow scientists to estimate past temperatures. Researchers are now drilling in search of ice more than a million years old, hoping to explain a puzzling shift in the rhythm of the ice ages that occurred long before humans existed. Each new core extends the archive, reminding us that the frozen continent at the bottom of the world remembers far more than it reveals at first glance.","questions":[{"type":"main","q":"What is the central idea of the passage?","options":["Ice cores record Earth's past atmosphere and show how unusual today's levels are.","Antarctica is the coldest and least explored continent on the entire planet.","European scientists were the first people ever to travel to Antarctica."],"answer":0},{"type":"vocab","q":"In the second paragraph, what does \"compressing\" most nearly mean?","options":["breaking apart into small pieces","pressing together into less space","melting slowly into liquid water"],"answer":1,"evidence":"In the interior of Antarctica, so little melting occurs that each year's snowfall is buried beneath the next, gradually compressing under its own accumulating weight."},{"type":"evidence","q":"Which sentence best supports the claim that current carbon dioxide levels are unusual?","options":["Layers of volcanic ash identify ancient eruptions, and variations in the chemistry of the water itself allow scientists to estimate past temperatures.","During the early 2000s, a European project known as EPICA drilled more than three kilometers into the ice at a site called Dome C.","Atmospheric carbon dioxide has now risen above four hundred and twenty parts per million, a level unmatched anywhere in the ice-core record."],"answer":2,"evidence":"Atmospheric carbon dioxide has now risen above four hundred and twenty parts per million, a level unmatched anywhere in the ice-core record."},{"type":"craft","q":"Why does the author describe the ice as an \"archive\"?","options":["To show that it stores records of the past that can be studied","To show that scientists keep the ice cores in a public library","To show that the ice is too old and fragile to be examined"],"answer":0}],"grade":11,"words":367,"auto":{"fk":11.4,"decodable":null,"checks":"pass"}},{"id":"pl-g11-02","pool":"placement-g11","title":"Open the Museum Doors for Free","genre":"argument","source":"app-original","license":"app-original","text":"Every year, millions of visitors walk into the Smithsonian's museums in Washington, D.C., without buying a ticket. They can stand beneath a whale skeleton, study the Wright brothers' flyer, or examine a lunch counter from the civil rights movement, all at no cost. That generosity is unusual. Admission to many major American art and science museums now costs twenty-five or thirty dollars for an adult, which means a family of four may spend more than a hundred dollars before seeing a single exhibit. Publicly funded museums should drop their general admission fees.\n\nThe central argument is about who museums serve. A museum that receives tax money, public land or tax-exempt status holds its collection partly on behalf of the public. When high prices keep out families with modest incomes, the public pays for an institution that only some of it can comfortably enter. Free admission turns a museum from a special-occasion destination into a place where a student can stop by for twenty minutes after school, return the next week, and slowly come to feel at home.\n\nThere is evidence that cost matters. In December 2001, the United Kingdom ended general admission charges at its national museums. Over the following decade, government figures showed that visits to the museums that had previously charged more than doubled.\n\nCritics argue that museums cannot afford to give up ticket revenue, and that concern is legitimate. Ticket sales help pay for guards, conservators and climate control. In 2018, the Metropolitan Museum of Art in New York ended its long-standing pay-what-you-wish policy for most out-of-state visitors, saying that too few people were paying enough. However, admission fees usually make up a modest share of a large museum's budget compared with donations, endowments and public funding. Governments and donors can fill the gap, as the British government did, if they decide that open access is worth paying for.\n\nMuseums exist to preserve shared history, art and knowledge for everyone. A ticket booth at the entrance quietly tells some visitors that the shared treasures are not quite theirs. Removing it sends a better message.","questions":[{"type":"claim","q":"Which reason supports the author's claim about publicly funded museums?","options":["They hold collections partly on behalf of the public.","They earn most of their money from ticket sales.","They attract mainly tourists from other countries."],"answer":0},{"type":"evidence","q":"Which sentence best supports the idea that cost affects how many people visit?","options":["Governments and donors can fill the gap, as the British government did, if they decide that open access is worth paying for.","Over the following decade, government figures showed that visits to the museums that had previously charged more than doubled.","In 2018, the Metropolitan Museum of Art in New York ended its long-standing pay-what-you-wish policy for most out-of-state visitors, saying that too few people were paying enough."],"answer":1,"evidence":"Over the following decade, government figures showed that visits to the museums that had previously charged more than doubled."},{"type":"claim","q":"Why does the author mention the Metropolitan Museum of Art?","options":["To prove that free museums attract no visitors at all","To praise a museum that recently dropped its fees","To present a fair example that supports the critics"],"answer":2},{"type":"craft","q":"What does the author suggest by saying a ticket booth \"quietly tells\" visitors something?","options":["Museum staff are often rude to visitors who cannot pay.","Prices can send an unspoken message about who belongs.","Ticket booths make too much noise inside the galleries."],"answer":1}],"grade":11,"words":356,"auto":{"fk":9.3,"decodable":null,"checks":"pass"}},{"id":"pl-g11-03","pool":"placement-g11","title":"Safe or Out","genre":"narrative","source":"app-original","license":"app-original","text":"Lucía had umpired forty-one youth baseball games that spring, and in all of them she had made exactly one rule for herself: never let the crowd make the call. It had seemed like an easy rule in March, when the bleachers held a handful of parents wrapped in blankets. It seemed considerably harder on a humid evening in June, with the league championship tied in the bottom of the final inning and nearly two hundred people pressed against the fence.\n\nThe runner on third was a small, fast twelve-year-old named Desmond, and when the batter lifted a fly ball into shallow center field, Lucía knew instantly what would happen. Desmond tagged the base, waited for the catch, and sprinted for home. The center fielder threw a strong, accurate ball, and the catcher caught it on one hop and swept his mitt toward the plate just as Desmond slid.\n\nDust exploded around them, and the crowd was already shouting, half of it yelling \"Safe!\" and half of it \"Out!\", as though volume could settle the matter.\n\nLucía had seen it clearly, or at least she believed she had. Desmond's left hand had brushed the corner of the plate a fraction of a second before the mitt touched his shoulder. She also knew, with an uncomfortable certainty, that the team in the field was coached by the father of her closest friend, and that the call she was about to make would end that team's season.\n\nFor a moment, she felt every face turned toward her, waiting, and she thought of how simple it would be to hesitate, to ask her partner at second base for help, to let someone else carry the weight. Her partner, however, had been watching the catch, not the plate.\n\nShe spread her arms wide. \"Safe!\"\n\nHalf of the crowd erupted with joy, and the other half erupted in a very different way. Her friend's father walked toward her, red-faced, and then stopped a few steps away, took a long breath, and simply nodded. Later, as Lucía packed her gear in the emptying parking lot, she realized that she did not feel triumphant. She felt something steadier than that, something closer to relief that she had kept her one rule when keeping it finally cost something.","questions":[{"type":"inference","q":"Why does the call feel especially hard for Lucía?","options":["She did not see the play and has to guess what happened.","The call will end the season for her friend's father's team.","Her partner at second base disagrees with her loudly."],"answer":1},{"type":"literal","q":"What did Lucía believe she saw at the plate?","options":["Desmond's hand brushed the plate before the mitt touched his shoulder.","The catcher dropped the ball just before he could tag Desmond's shoulder.","Desmond left third base early, before the center fielder caught the ball."],"answer":0,"evidence":"Desmond's left hand had brushed the corner of the plate a fraction of a second before the mitt touched his shoulder."},{"type":"craft","q":"What is the effect of the phrase \"as though volume could settle the matter\"?","options":["It shows that the crowd is helping Lucía make the call.","It shows that the noise in the park is dangerously loud.","It suggests that the crowd's shouting has no real authority."],"answer":2},{"type":"theme","q":"Which theme does the story develop?","options":["Integrity matters most when keeping it comes at a cost.","Winning a championship is worth any kind of sacrifice.","Friends should always support one another's teams."],"answer":0}],"grade":11,"words":383,"auto":{"fk":7.5,"decodable":null,"checks":"pass"}},{"id":"pl-g12-01","pool":"placement-g12","title":"The Other Carbon Problem","genre":"informational","source":"app-original","license":"app-original","text":"Discussions of carbon dioxide emissions usually focus on the atmosphere, where the gas traps heat and warms the planet. Far less public attention goes to the ocean, which has absorbed roughly a quarter to a third of the carbon dioxide released by human activity since the beginning of the industrial era. This absorption has slowed atmospheric warming considerably, but it has not been free. When carbon dioxide dissolves in seawater, it reacts to form carbonic acid, and the ocean becomes measurably more acidic. Scientists call the process ocean acidification, and its consequences are only beginning to be understood.\n\nThe change sounds modest when it is expressed in the units chemists use. The average pH of the ocean's surface has fallen from about 8.2 to about 8.1 over the past two centuries. Seawater remains slightly alkaline, not acidic in the everyday sense of the word. But the pH scale is logarithmic, so a decline of a tenth of a unit corresponds to an increase of roughly thirty percent in the concentration of hydrogen ions. For organisms that evolved in a chemically stable environment over millions of years, a shift of that magnitude within a few human generations is abrupt.\n\nThe organisms most immediately affected are those that build shells or skeletons from calcium carbonate, including corals, oysters, clams, and tiny swimming snails called pteropods. As seawater becomes more acidic, the concentration of carbonate ions, the building blocks these creatures need, declines. Shell construction becomes more costly in energy, and in sufficiently corrosive water, existing shells can begin to dissolve.\n\nSome of the earliest economic evidence came from the shellfish industry in the Pacific Northwest of the United States. Beginning in the mid-2000s, oyster hatcheries in Oregon and Washington experienced repeated die-offs of larvae, sometimes losing most of a season's production. Researchers eventually linked the losses to upwelling, in which deep water that is naturally rich in carbon dioxide rises toward the coast, made more corrosive by the additional carbon absorbed from the atmosphere. Hatcheries responded by monitoring the chemistry of incoming water and adjusting it before exposing young oysters, a solution that works in a tank but cannot be applied to the open ocean.","questions":[{"type":"main","q":"What is the central idea of the passage?","options":["Ocean absorption of carbon slows warming but harms marine chemistry and life.","Ocean absorption of carbon has solved the problem of global warming entirely.","Ocean absorption of carbon mainly benefits oysters and other shellfish farms."],"answer":0},{"type":"why","q":"Why does the author explain that the pH scale is logarithmic?","options":["To show that a small number reflects a large chemical change","To prove that seawater has become strongly acidic like vinegar","To argue that chemists have exaggerated the size of the change"],"answer":0},{"type":"vocab","q":"As used in the passage, what does \"upwelling\" describe?","options":["Deep water rising toward the coast","Shells growing thicker in cold water","Rain carrying carbon into rivers"],"answer":0,"evidence":"Researchers eventually linked the losses to upwelling, in which deep water that is naturally rich in carbon dioxide rises toward the coast, made more corrosive by the additional carbon absorbed from the atmosphere."},{"type":"inference","q":"What does the final sentence suggest about the hatcheries' solution?","options":["It protects one industry but leaves the wider problem unsolved.","It will soon be used to treat the chemistry of the whole ocean.","It has made ocean acidification harmless for wild shellfish."],"answer":0}],"grade":12,"words":365,"auto":{"fk":12,"decodable":null,"checks":"pass"}},{"id":"pl-g12-02","pool":"placement-g12","title":"In Defense of Difficult Books","genre":"argument","source":"app-original","license":"app-original","text":"Every few years, a familiar proposal circulates among educators and parents: high school English classes should replace older, difficult books with shorter, more contemporary texts that students will actually finish. The argument is understandable. Teachers know that many students struggle with archaic vocabulary, long sentences, and unfamiliar historical settings, and some students quietly substitute online summaries for the reading itself. Nevertheless, abandoning challenging literature would be a mistake, because the difficulty is not an obstacle to the education these books provide. To a considerable extent, it is the education.\n\nReading a demanding text is a form of sustained effort that few other activities in a student's day require. A novel written in the nineteenth century asks readers to hold several characters, motives, and plot threads in mind across hundreds of pages, to tolerate uncertainty about what a passage means, and to return to it until the meaning clarifies. These are precisely the capacities that college courses, complex jobs, and responsible citizenship demand. A curriculum composed entirely of accessible texts may produce students who read more pages, but it is unlikely to produce students who can read the difficult documents that adult life inevitably presents, from legal contracts to scientific reports.\n\nOlder books also offer something contemporary ones cannot: genuine distance. Encountering the assumptions of another century, including assumptions that now seem mistaken or unjust, forces readers to recognize that their own assumptions are also products of a particular time. That recognition is uncomfortable, and it should be. A literature that only reflects the present back to its readers flatters them; a literature that speaks from elsewhere asks them to listen.\n\nNone of this means that contemporary literature lacks value, or that teachers should assign difficult books without support. The strongest English classes combine older and newer works, and they help students through the hardest passages with discussion, background, and patience. The answer to a demanding book is not a simpler book. It is better teaching, and the expectation that young readers are capable of more than we sometimes assume.","questions":[{"type":"claim","q":"What is the author's central claim?","options":["Challenging older books should remain part of English classes.","Contemporary novels should replace older books in high schools.","Students should read online summaries before each assigned book."],"answer":0},{"type":"claim","q":"Which counterclaim does the author acknowledge in the first paragraph?","options":["Many students struggle with or skip difficult older texts.","Older books are too expensive for most schools to buy.","Teachers dislike discussing older books with students."],"answer":0},{"type":"evidence","q":"Which sentence best supports the claim that difficult reading builds skills for adult life?","options":["These are precisely the capacities that college courses, complex jobs, and responsible citizenship demand.","Teachers know that many students struggle with archaic vocabulary, long sentences, and unfamiliar historical settings, and some students quietly substitute online summaries for the reading itself.","That recognition is uncomfortable, and it should be."],"answer":0,"evidence":"These are precisely the capacities that college courses, complex jobs, and responsible citizenship demand."},{"type":"author","q":"What does the author mean by saying older books offer \"genuine distance\"?","options":["They help readers see their own beliefs as shaped by time.","They are usually set in countries far from the reader.","They keep students from relating to any of the characters."],"answer":0}],"grade":12,"words":339,"auto":{"fk":13.5,"decodable":null,"checks":"pass"}},{"id":"pl-g12-03","pool":"placement-g12","title":"The Gap in Line Seven","genre":"narrative","source":"app-original","license":"app-original","text":"Noor had spent three weeks constructing the proof, and on Thursday night, at a quarter past eleven, she finally believed it was complete. The problem came from a competitive summer mathematics program she hoped to attend, and it required applicants to demonstrate that a particular kind of numerical sequence could never repeat itself. She had filled most of a notebook with failed attempts before the idea arrived, almost casually, while she was rinsing a cereal bowl. By midnight the argument covered two clean pages, and every step seemed to click into the next like the teeth of a zipper.\n\nThe application was due Saturday. Her older brother, who studied engineering and claimed to have forgotten all mathematics unrelated to bridges, read it over her shoulder and declared it convincing, while her mother observed only that she looked exhausted. Noor typed the proof, saved it and went to bed feeling, for the first time in weeks, that the problem belonged to her.\n\nOn Friday morning, waiting for the bus, she reread the proof on her phone, intending only to admire it. In line seven she stopped. She had divided both sides of an equation by a quantity she had called k, and she had never shown that k could not be zero. In most situations it obviously was not, but if k were zero, the division was meaningless, and everything that followed would collapse.\n\nHer first impulse was to argue with herself: surely the reviewers would never notice, and surely the exceptional case was too unlikely to matter. She recognized that persuasive voice almost immediately. It was the same voice that told her a test answer was probably fine so that she would not have to check it. Mathematics, her teacher liked to remind the class, is indifferent to how hard you worked; it cares only whether the argument is true.\n\nShe spent her lunch period in the library with a pencil. The situation in which k equaled zero turned out to be stubborn, and for nearly an hour every approach seemed to lead nowhere. Then she saw that it produced a pattern of its own, a simpler one, which could be handled in a short separate argument. The correction added half a page and made the proof considerably less elegant, interrupting the clean sweep she had been so proud of.\n\nThat evening she submitted the longer version. Before closing the laptop, she added a sentence at the end, noting that an earlier draft had overlooked the zero case. She was uncertain whether the reviewers would care to know, but she was certain that she did.","questions":[{"type":"literal","q":"What mistake did Noor find in line seven of her proof?","options":["She had divided by k and never shown that k could not be zero.","She had copied the wrong number pattern from the application.","She had skipped the final step that her brother pointed out."],"answer":0,"evidence":"She had divided both sides of an equation by a quantity she had called k, and she had never shown that k could not be zero."},{"type":"craft","q":"What does the comparison to \"the teeth of a zipper\" suggest about the proof?","options":["Its steps seemed to fit together smoothly and completely.","Its argument was likely to come apart under any pressure.","Its ideas were borrowed from an ordinary household object."],"answer":0},{"type":"inference","q":"Why does Noor recognize the voice claiming the reviewers will miss the error?","options":["It is the same excuse she has used to avoid checking her work.","It sounds exactly like her brother's advice about engineering.","It belongs to her teacher, who warned her about the deadline."],"answer":0},{"type":"theme","q":"Which theme does the story best develop?","options":["Honest work means facing flaws even when a result feels finished.","Elegant solutions are always more correct than complicated ones.","Deadlines matter more than accuracy in competitive applications."],"answer":0}],"grade":12,"words":435,"auto":{"fk":9.6,"decodable":null,"checks":"pass"}},{"id":"pl-g3-01","pool":"placement-g3","title":"Tiny Hummingbirds","genre":"informational","source":"app-original","license":"app-original","text":"Hummingbirds are the smallest birds in the world. The tiniest kind, the bee hummingbird, is only about two inches long. It lives on the island of Cuba.\n\nA hummingbird's wings move so fast that they look like a blur. Many hummingbirds beat their wings more than fifty times each second. The wings make a soft humming sound, and that is how the birds got their name.\n\nHummingbirds can hover in one spot, like a tiny helicopter. They can even fly backward! Very few other birds can do that.\n\nAll that flying takes a lot of energy. A hummingbird must eat many times an hour. It sips sweet nectar from flowers with its long tongue. It also snaps up small insects.\n\nAt night, a hummingbird rests very deeply. Its body cools down and its heart slows, which saves energy until morning.","questions":[{"type":"main","q":"What is this passage mostly about?","options":["how hummingbirds fly and eat","how flowers make sweet nectar","how birds build their nests"],"answer":0},{"type":"literal","q":"How long is the bee hummingbird?","options":["about two feet","about two inches","about ten inches"],"answer":1,"evidence":"The tiniest kind, the bee hummingbird, is only about two inches long."},{"type":"why","q":"How did hummingbirds get their name?","options":["from the songs they sing","from the flowers they visit","from the sound of their wings"],"answer":2},{"type":"vocab","q":"What does hover mean in this passage?","options":["stay still in the air","fly far away fast","dive to the ground"],"answer":0,"evidence":"Hummingbirds can hover in one spot, like a tiny helicopter."}],"grade":3,"words":140,"auto":{"fk":3.9,"decodable":null,"checks":"pass"}},{"id":"pl-g3-02","pool":"placement-g3","title":"Room for Two","genre":"narrative","source":"app-original","license":"app-original","text":"Lucia was halfway to the bus stop when the sky turned dark. Big, heavy raindrops began to fall. She had forgotten her umbrella on the kitchen table.\n\nAt the bus stop, an older man stood under a wide black umbrella. He was holding a cane and a bag of groceries. Lucia stood a few steps away, getting wetter by the second.\n\n\"Come stand under here,\" the man said kindly. \"There's room for two.\"\n\nLucia hesitated, then stepped under the umbrella. \"Thank you,\" she said. She noticed that his grocery bag was starting to rip. \"Can I hold that for you?\"\n\nWhen the bus came, Lucia carried his bag up the steps and found him a seat. The man smiled. \"We make a good team,\" he said.\n\nLucia smiled back. Being soaked didn't seem so bad now.","questions":[{"type":"literal","q":"What did Lucia leave at home?","options":["her backpack","her umbrella","her lunch"],"answer":1,"evidence":"She had forgotten her umbrella on the kitchen table."},{"type":"why","q":"Why does the man share his umbrella?","options":["Lucia is getting wet.","He wants to talk about buses.","Lucia asked him for help."],"answer":0},{"type":"inference","q":"Which word best describes Lucia?","options":["lazy","rude","helpful"],"answer":2},{"type":"theme","q":"What does the man mean by \"We make a good team\"?","options":["They play on a sports team.","They helped each other.","They are going to a game."],"answer":1}],"grade":3,"words":136,"auto":{"fk":2.6,"decodable":null,"checks":"pass"}},{"id":"pl-g3-03","pool":"placement-g3","title":"Up, Up and Away","genre":"informational","source":"app-original","license":"app-original","text":"Hot air balloons can float high above the ground without wings or engines. How do they do it? The secret is hot air.\n\nA hot air balloon has three main parts. The giant cloth bag on top is called the envelope. Under it hangs a basket where people ride. Between them is a burner that makes a big flame.\n\nWhen the pilot turns on the burner, it heats the air inside the envelope. Hot air is lighter than the cooler air around it. So the hot air rises, and it lifts the whole balloon up into the sky.\n\nTo come back down, the pilot lets the air inside cool off. As it cools, the balloon slowly sinks. The pilot cannot steer like a car driver. Instead, the balloon floats wherever the wind blows it.\n\nThe first hot air balloon flight with people on board took place in France in 1783.","questions":[{"type":"vocab","q":"What is the envelope of a hot air balloon?","options":["the riding basket","the hot flame","the big cloth bag"],"answer":2,"evidence":"The giant cloth bag on top is called the envelope."},{"type":"why","q":"What makes a hot air balloon rise?","options":["heated air inside it","a strong motor","big flapping wings"],"answer":0},{"type":"literal","q":"Where did the first balloon flight with people happen?","options":["in Spain","in France","in China"],"answer":1,"evidence":"The first hot air balloon flight with people on board took place in France in 1783."},{"type":"inference","q":"Why can't a pilot choose exactly where to land?","options":["The basket is too heavy.","The flame is too small.","The wind moves the balloon."],"answer":2}],"grade":3,"words":150,"auto":{"fk":2.9,"decodable":null,"checks":"pass"}},{"id":"pl-g4-01","pool":"placement-g4","title":"The First Balloon Riders","genre":"informational","source":"app-original","license":"app-original","text":"In the 1780s, two brothers in France named Joseph and Étienne Montgolfier noticed something interesting. When they held a paper bag over a fire, the bag floated up toward the ceiling. Hot air, they realized, is lighter than the cooler air around it. If they could trap enough hot air inside a giant bag, maybe it could lift something heavy.\n\nThe brothers ran a paper-making business, so they had plenty of materials. They built a huge balloon from cloth lined with paper. In 1783, they tested it in front of the king and queen of France.\n\nBut who would ride in it? No one knew whether a living creature could survive so high above the ground. So the first passengers were a sheep, a duck, and a rooster. The animals were placed in a basket that hung below the balloon. A fire heated the air inside, and the balloon rose high into the sky while a large crowd cheered.\n\nThe flight lasted about eight minutes. The balloon drifted down into a forest about two miles away. When people ran to the basket, they found all three animals alive and well.\n\nThat test gave the inventors courage. Just two months later, two men climbed into a Montgolfier balloon in Paris and floated over the city for about twenty-five minutes. They became the first people ever to fly.","questions":[{"type":"main","q":"What is the passage mostly about?","options":["How the first hot air balloon flights happened","How the brothers ran a paper-making business","How animals are trained to ride in baskets"],"answer":0},{"type":"why","q":"Why did animals ride in the balloon before people did?","options":["No one knew if a living thing could survive the flight.","The king and queen did not want to ride in the basket.","The basket was too small to hold any grown person."],"answer":0},{"type":"evidence","q":"Which sentence best supports the idea that the animal test was a success?","options":["The animals were placed in a basket that hung below the balloon.","When people ran to the basket, they found all three animals alive and well.","They built a huge balloon from cloth lined with paper."],"answer":1,"evidence":"When people ran to the basket, they found all three animals alive and well."},{"type":"literal","q":"How long did the first people float over Paris?","options":["about twenty-five minutes","about eight minutes","about forty-five minutes"],"answer":0,"evidence":"Just two months later, two men climbed into a Montgolfier balloon in Paris and floated over the city for about twenty-five minutes."}],"grade":4,"words":228,"auto":{"fk":5.3,"decodable":null,"checks":"pass"}},{"id":"pl-g4-02","pool":"placement-g4","title":"The Chess Rematch","genre":"narrative","source":"app-original","license":"app-original","text":"Every Tuesday after school, Hannah played chess against her grandfather at the kitchen table. And every Tuesday, she lost.\n\nGrandpa Eli never let her win on purpose. “If I did,” he said, “you would never know when you really beat me.” Hannah understood, but losing week after week still made her want to sweep all the pieces onto the floor.\n\nOne Tuesday, after another quick defeat, Grandpa slid a worn book across the table. It was full of diagrams of famous chess games. “Don't just play,” he said. “Study. Look at what the great players did, and ask yourself why.”\n\nFor the next month, Hannah read the book on the bus and before bed. She set up the board in her room and replayed the games move by move. She learned that strong players protect their king early and that a knight in the center of the board is far more powerful than one stuck in a corner.\n\nWhen the next Tuesday came, Hannah played slowly. She thought before every move. She castled her king to safety and moved her knights toward the center. Grandpa raised his eyebrows.\n\nAn hour later, Hannah slid her queen across the board. “Checkmate,” she said, hardly believing it.\n\nGrandpa stared at the board. Then he laughed so loudly that the cat jumped off the windowsill. “Now,” he said, setting up the pieces again, “you know you really earned it.”","questions":[{"type":"theme","q":"What lesson does Hannah learn in the story?","options":["Studying and practice can help you improve.","Grandparents should let children win games.","Chess is a game that depends mostly on luck."],"answer":0},{"type":"why","q":"Why does Grandpa Eli refuse to let Hannah win on purpose?","options":["He wants her to know when she truly wins.","He does not like to lose any chess games.","He thinks that chess is too hard for her."],"answer":0},{"type":"evidence","q":"Which sentence best shows that Hannah worked hard to get better?","options":["She set up the board in her room and replayed the games move by move.","Then he laughed so loudly that the cat jumped off the windowsill.","Hannah understood, but losing week after week still made her want to sweep all the pieces onto the floor."],"answer":0,"evidence":"She set up the board in her room and replayed the games move by move."},{"type":"inference","q":"Why does Grandpa raise his eyebrows during the game?","options":["He is surprised by how well Hannah is playing.","He is annoyed that Hannah is moving too slowly.","He is confused about the rules for the knights."],"answer":0}],"grade":4,"words":235,"auto":{"fk":4.1,"decodable":null,"checks":"pass"}},{"id":"pl-g4-03","pool":"placement-g4","title":"Why Popcorn Pops","genre":"informational","source":"app-original","license":"app-original","text":"Pour some popcorn kernels into a hot pot, and soon you will hear a burst of pops. In seconds, hard little seeds turn into fluffy white puffs. What makes that happen? The answer is hidden inside each kernel.\n\nA popcorn kernel has three main parts. On the outside is a hard, shiny shell. Inside the shell is soft starch, which is the food the seed would use to grow. Mixed into the starch is a tiny drop of water.\n\nWhen the kernel gets hot, the water inside turns into steam. Steam takes up much more space than water, so it pushes hard against the shell. The shell is strong, so the pressure keeps building. At the same time, the heat makes the starch soft and gooey.\n\nFinally, the shell cannot hold any longer. It bursts open with a pop! The soft starch puffs out into a foam and cools into the crunchy shape you eat.\n\nNot every kind of corn can do this trick. Popcorn is special because its shell is hard enough to trap the steam until the last moment. Other corn has a weaker shell that lets steam leak out.\n\nSometimes a few kernels stay hard at the bottom of the bowl. Those kernels may have dried out too much or had a crack in the shell. Without enough trapped steam, they never pop.","questions":[{"type":"main","q":"What is the main idea of the passage?","options":["Steam trapped inside a kernel makes popcorn burst open.","Popcorn kernels pop because they are full of tiny seeds.","All kinds of corn will pop if they are cooked long enough."],"answer":0},{"type":"literal","q":"What happens to the water when a kernel gets hot?","options":["It freezes into ice.","It turns into steam.","It leaks into the pot."],"answer":1,"evidence":"When the kernel gets hot, the water inside turns into steam."},{"type":"evidence","q":"Which sentence best explains why regular corn fails to pop well?","options":["Mixed into the starch is a tiny drop of water.","In seconds, hard little seeds turn into fluffy white puffs.","Other corn has a weaker shell that lets steam leak out."],"answer":2,"evidence":"Other corn has a weaker shell that lets steam leak out."},{"type":"vocab","q":"In the passage, what does pressure mean?","options":["a strong push","a quick sound","a bit of food"],"answer":0,"evidence":"The shell is strong, so the pressure keeps building."}],"grade":4,"words":226,"auto":{"fk":3.3,"decodable":null,"checks":"pass"}},{"id":"pl-g5-01","pool":"placement-g5","title":"Rivers of Ice","genre":"informational","source":"app-original","license":"app-original","text":"A glacier is a huge mass of ice that moves slowly over land. Glaciers form in places where more snow falls in winter than melts in summer. Year after year, the snow piles up and presses down on the layers beneath it. Over time, the weight squeezes the old snow into solid ice.\n\nWhen a glacier becomes thick and heavy enough, it begins to flow downhill, a little like extremely thick honey. Most glaciers move only a few inches or feet each day, but some have been measured moving much faster. As a glacier travels, it acts like a giant piece of sandpaper. Rocks frozen into the bottom of the ice scrape against the ground, grinding away soil and stone.\n\nThis scraping can change the shape of the land. Rivers usually carve narrow valleys shaped like the letter V. A glacier, however, is much wider than a river, so it carves broad valleys shaped like the letter U. Yosemite Valley in California is a famous example of a valley carved by ice.\n\nGlaciers also leave things behind. When the ice melts, it drops the rocks and dirt it was carrying. Some of these boulders are as big as houses and sit far from where they started. Scientists use them as clues to figure out where glaciers once flowed.\n\nToday, glaciers cover about a tenth of Earth's land. Because the planet is warming, many of them are shrinking, and scientists watch them closely to understand how our climate is changing.","questions":[{"type":"main","q":"What is the passage mostly about?","options":["how rivers carve narrow valleys in rock","how honey flows slowly down a hill","how glaciers form, move, and shape the land"],"answer":2},{"type":"literal","q":"What shape of valley does a glacier carve?","options":["a valley shaped like the letter V","a valley shaped like the letter U","a valley shaped like the letter S"],"answer":1,"evidence":"A glacier, however, is much wider than a river, so it carves broad valleys shaped like the letter U."},{"type":"vocab","q":"In the passage, what does the word broad mean?","options":["narrow","deep","wide"],"answer":2,"evidence":"A glacier, however, is much wider than a river, so it carves broad valleys shaped like the letter U."},{"type":"evidence","q":"Which sentence best explains how a glacier wears away the ground?","options":["Rocks frozen into the bottom of the ice scrape against the ground, grinding away soil and stone.","When a glacier becomes thick and heavy enough, it begins to flow downhill, a little like extremely thick honey.","Yosemite Valley in California is a famous example of a valley carved by ice."],"answer":0,"evidence":"Rocks frozen into the bottom of the ice scrape against the ground, grinding away soil and stone."}],"grade":5,"words":249,"auto":{"fk":5.8,"decodable":null,"checks":"pass"}},{"id":"pl-g5-02","pool":"placement-g5","title":"The Science Fair Volcano","genre":"narrative","source":"app-original","license":"app-original","text":"Hana had promised herself that this year's science fair project would not be a baking soda volcano. Everyone made a volcano. Instead, she wanted to build a small windmill that could power a light bulb. She spent three weekends cutting blades from plastic bottles, attaching them to a tiny motor, and testing her design in front of a box fan.\n\nOn the night before the fair, disaster struck. As Hana carried the windmill to the kitchen table, she tripped over her brother's backpack. The windmill crashed to the floor, and two of the blades snapped in half. The fair started at nine the next morning, and there was no time to start over.\n\nHana sat on the floor and stared at the pieces. Her grandfather, who had been reading in the next room, came in and knelt beside her. Instead of telling her it would be fine, he picked up a broken blade and turned it over in his hands. \"What did you learn when you were testing it?\" he asked.\n\nHana thought about it. She had learned that longer blades spun faster but wobbled more. She had learned that tilting the blades made a huge difference. Slowly, she realized that her notes, photos, and test results were still perfectly safe in her notebook.\n\nThe next morning, Hana set up the broken windmill beside a poster that explained everything she had discovered. When the judges stopped at her table, she showed them her data and explained what she would change next time. She did not win first place, but one judge wrote on her score sheet, \"Excellent thinking like a real engineer.\" Hana decided that was even better than a ribbon.","questions":[{"type":"theme","q":"What lesson does Hana learn in the story?","options":["Winning a ribbon is the only reason to enter a science fair.","It is always safer to build the same project as everyone else.","What you learn from your work matters even when things go wrong."],"answer":2},{"type":"sequence","q":"What happened right after Hana tripped over the backpack?","options":["The windmill crashed and two blades snapped.","Her grandfather picked up a broken blade.","The judges stopped at her table."],"answer":0,"evidence":"The windmill crashed to the floor, and two of the blades snapped in half."},{"type":"inference","q":"Why does Grandfather ask Hana what she learned?","options":["He wants her to start building a baking soda volcano.","He wants her to stay home and skip the science fair.","He wants her to see that her work still has value."],"answer":2},{"type":"evidence","q":"Which sentence best shows how Hana feels about the judge's comment?","options":["Hana decided that was even better than a ribbon.","Everyone made a volcano.","The fair started at nine the next morning, and there was no time to start over."],"answer":0,"evidence":"Hana decided that was even better than a ribbon."}],"grade":5,"words":281,"auto":{"fk":5.2,"decodable":null,"checks":"pass"}},{"id":"pl-g5-03","pool":"placement-g5","title":"Every School Needs a Garden","genre":"argument","source":"app-original","license":"app-original","text":"Every elementary school should have a garden where students can grow their own food. A school garden is more than a patch of dirt. It is an outdoor classroom that teaches science, builds healthy habits, and brings people together.\n\nFirst, gardens make science come alive. Instead of only reading about how plants grow, students can watch a seed sprout, measure a bean plant each week, and test which soil works best. Teachers say that students remember lessons better when they can touch, smell, and observe what they are learning.\n\nSecond, gardens can help students eat healthier. Many children say they dislike vegetables, but researchers have found that kids are more willing to try foods they have grown themselves. A child who has spent weeks caring for a row of carrots is often excited to taste one.\n\nThird, gardens build community. Planting, weeding, and watering take teamwork. Families can volunteer on weekends, and older students can teach younger ones. Some schools even share their harvest with local food pantries.\n\nSome people argue that gardens cost too much money and take time away from other subjects. These concerns are understandable, but a garden does not need to be large or expensive. A few raised beds and donated seeds are enough to begin. In addition, garden lessons can include math, reading, and writing, so students are not losing learning time at all.\n\nA school garden helps students grow in many ways. It is a small investment that can make a big difference, and every school should plant one.","questions":[{"type":"claim","q":"What is the author's main claim?","options":["Every elementary school should have a garden.","Students should only learn science outdoors.","School gardens cost far too much money."],"answer":0},{"type":"evidence","q":"Which sentence best supports the idea that gardens help kids eat healthier?","options":["Many children say they dislike vegetables, but researchers have found that kids are more willing to try foods they have grown themselves.","Families can volunteer on weekends, and older students can teach younger ones.","Instead of only reading about how plants grow, students can watch a seed sprout, measure a bean plant each week, and test which soil works best."],"answer":0,"evidence":"Many children say they dislike vegetables, but researchers have found that kids are more willing to try foods they have grown themselves."},{"type":"claim","q":"How does the author respond to the concern about cost?","options":["by saying gardens should be very large","by saying a garden can start small and cheap","by saying schools should raise their taxes"],"answer":1},{"type":"vocab","q":"In the passage, what does the word harvest mean?","options":["the seeds that are planted","the tools used for digging","the crops that are gathered"],"answer":2,"evidence":"Some schools even share their harvest with local food pantries."}],"grade":5,"words":255,"auto":{"fk":6.4,"decodable":null,"checks":"pass"}},{"id":"pl-g6-01","pool":"placement-g6","title":"The Wrong Bus","genre":"narrative","source":"app-original","license":"app-original","text":"On her second day in a new city, Aiyana realized she was on the wrong bus. The sign above the driver had said 22 when she climbed aboard, but now, as the bus turned away from the river, she noticed a small letter after the number. Her school was on the 22 route, and she had absolutely no idea where the 22X traveled.\n\nHer first instinct was to panic, because her phone battery had run out that morning, she didn't recognize anyone on the bus, and the neighborhoods outside looked nothing like the ones near her new apartment.\n\nThen she remembered something her older brother had told her before she left. \"When you're lost, slow down and look for information. The answer is usually right in front of you.\"\n\nAiyana took a deep breath and carefully studied her surroundings. Above the windows hung a map of the route, with every stop marked by a dot. She traced the line with her finger and discovered that the 22X crossed her own route at a stop called Maple and Fifth. If she got off there, she could catch the regular 22 and still reach school on time.\n\nWhen the bus reached Maple and Fifth, she stepped off and checked the sign on the pole. It listed both buses, and seven minutes later, the correct one arrived.\n\nShe walked into her first class just as the bell rang. Her teacher asked whether she had found the building easily. Aiyana smiled and answered, \"Not exactly. But I found it.\"\n\nThat evening, she drew a small map of her routes in the back of her notebook. She didn't plan to get lost again, but if she did, she would know exactly how to find her way.","questions":[{"type":"main","q":"Which sentence best summarizes the story?","options":["A girl misses school because her phone runs out of power on a bus.","A girl takes the wrong bus but uses a route map to reach school.","A girl rides the bus with her brother so he can show her the way."],"answer":1},{"type":"literal","q":"Where did Aiyana find the information she needed?","options":["on a sign outside her school","on a phone that a stranger lent","on a route map above the windows"],"answer":2,"evidence":"Above the windows hung a map of the route, with every stop marked by a dot."},{"type":"theme","q":"Which theme does the story develop?","options":["Staying calm and looking for clues can solve a problem.","Big cities are much too confusing for new students.","It is always best to ask a stranger for help first."],"answer":0},{"type":"inference","q":"What does Aiyana mean when she tells her teacher, \"But I found it\"?","options":["She found a shortcut that made her trip faster.","She solved the problem herself after a rough start.","She found her lost phone on the way to class."],"answer":1}],"grade":6,"words":291,"auto":{"fk":5.8,"decodable":null,"checks":"pass"}},{"id":"pl-g6-02","pool":"placement-g6","title":"The Fish That Spits","genre":"informational","source":"app-original","license":"app-original","text":"Imagine a fish that hunts insects sitting on leaves above the water. That sounds impossible, but the archerfish does it every day. Archerfish live in mangrove swamps and river mouths in Southeast Asia, India and northern Australia. Most are no longer than a person's hand, with silvery bodies marked by dark stripes.\n\nWhen an archerfish spots a beetle or a spider on a low branch, it swims just under the surface and takes aim. Then it presses its tongue against a groove in the roof of its mouth, forming a narrow tube. By snapping its gill covers shut, the fish forces a jet of water through the tube and out of its mouth. If the aim is good, the insect is knocked off the leaf and tumbles into the water, where the fish gobbles it up.\n\nHitting a target is harder than it looks. Light bends when it passes from air into water, so an insect seen from below is not exactly where it appears to be. Archerfish somehow correct for this bending. Scientists have also discovered that the fish adjust each jet so that the water gathers into a heavy blob just as it reaches its target. Large adults can strike prey more than a meter away.\n\nYoung archerfish miss often, but they improve with practice. In laboratory experiments, young fish also learned faster by watching skilled fish hit moving targets.\n\nThe archerfish shows that a small brain can solve a complicated physics problem. For a hungry fish, that skill means dinner. For an insect resting on a leaf, it is very bad news.","questions":[{"type":"main","q":"What is the main idea of the passage?","options":["Archerfish are large fish that leap from rivers to catch small birds.","Archerfish catch insects by spitting carefully aimed jets of water.","Archerfish live in mangrove swamps and eat only plants near shore."],"answer":1},{"type":"sequence","q":"What does an archerfish do just before it snaps its gill covers shut?","options":["presses its tongue against a groove","leaps high out of the murky water","gobbles up the fallen beetle whole"],"answer":0,"evidence":"Then it presses its tongue against a groove in the roof of its mouth, forming a narrow tube."},{"type":"evidence","q":"Which sentence best supports the idea that young archerfish can learn from others?","options":["Light bends when it passes from air into water, so an insect seen from below is not exactly where it appears to be.","If the aim is good, the insect is knocked off the leaf and tumbles into the water, where the fish gobbles it up.","In laboratory experiments, young fish also learned faster by watching skilled fish hit moving targets."],"answer":2,"evidence":"In laboratory experiments, young fish also learned faster by watching skilled fish hit moving targets."},{"type":"author","q":"Why does the author explain that light bends when it enters water?","options":["to explain how archerfish see in the dark","to show why aiming at insects is difficult","to describe why swamp water looks green"],"answer":1}],"grade":6,"words":265,"auto":{"fk":6.5,"decodable":null,"checks":"pass"}},{"id":"pl-g6-03","pool":"placement-g6","title":"Every Student Should Learn to Cook","genre":"argument","source":"app-original","license":"app-original","text":"Most students spend years learning math, science and history, but many graduate without knowing how to cook a simple meal. Schools should require every middle school student to take a basic cooking class.\n\nFirst, cooking is a life skill that everyone needs. Sooner or later, nearly every person has to feed themselves. Students who know how to prepare healthy meals are less likely to depend on fast food and packaged snacks, which are often high in salt and sugar.\n\nSecond, cooking teaches other subjects in a practical way. Doubling a recipe requires fractions. Watching bread rise is a lesson in chemistry, because yeast releases a gas that makes the dough expand. Following a recipe step by step also builds reading skills and patience.\n\nThird, cooking can save families money. A meal made at home usually costs much less than the same meal bought at a restaurant. Students who learn to cook can help their families prepare affordable dinners and pack their own lunches.\n\nSome people argue that schools do not have the time or money for cooking classes. They point out that kitchens are expensive to build and that the school day is already full. These are fair concerns, but a cooking class does not require a fancy kitchen. Many schools teach basic skills with portable burners, a few cutting boards and a sink. Cooking lessons can also be combined with science or health classes instead of being added as a separate subject.\n\nLearning to cook gives students independence, confidence and skills they will use every day for the rest of their lives. That is a lesson worth making room for.","questions":[{"type":"claim","q":"What is the author's main claim?","options":["Middle schools should require a basic cooking class.","Students should eat lunch at home instead of school.","Science classes should be replaced by cooking class."],"answer":0},{"type":"evidence","q":"Which sentence best supports the idea that cooking can teach math?","options":["A meal made at home usually costs much less than the same meal bought at a restaurant.","Doubling a recipe requires fractions.","Sooner or later, nearly every person has to feed themselves."],"answer":1,"evidence":"Doubling a recipe requires fractions."},{"type":"claim","q":"Which counterclaim does the author respond to?","options":["Students already know how to cook healthy meals.","Restaurants are cheaper than cooking at home.","Schools lack the time and money for cooking classes."],"answer":2},{"type":"vocab","q":"What does \"affordable\" mean in paragraph 4?","options":["low enough in cost","very quick to make","full of vegetables"],"answer":0,"evidence":"Students who learn to cook can help their families prepare affordable dinners and pack their own lunches."}],"grade":6,"words":271,"auto":{"fk":6.7,"decodable":null,"checks":"pass"}},{"id":"pl-g7-01","pool":"placement-g7","title":"Translating for My Father","genre":"narrative","source":"app-original","license":"app-original","text":"The landlord spoke quickly, the way people do when they assume no one will stop them. My father sat beside me at our small kitchen table, nodding politely as if he understood every word. He did not, which was exactly why I was there.\n\n\"He's saying the heater will be fixed by Friday,\" I told my father in Vietnamese. His shoulders relaxed a little, and he leaned back in his chair. Then the landlord added something about a fee, and I hesitated.\n\nI was thirteen, and I had been translating for my parents since I was eight. I had translated at the bank, at the pharmacy and at parent-teacher conferences where I was the student being discussed. Usually I simply passed the words along, like carrying water from one bucket to another. But sometimes the words were heavy, and I was tempted to spill a little on purpose.\n\n\"What about the fee?\" my father asked. He had noticed my pause, as he always did.\n\nI could have softened it. I could have said the fee was small or that the landlord was only joking. Instead I took a deep breath and told him exactly what the man had said: the repair would cost us an extra eighty dollars, even though the lease said that repairs were the landlord's responsibility.\n\nMy father was quiet for a moment. Then he stood, walked to the drawer by the sink and returned with a folded copy of the lease. He placed it on the table and tapped one paragraph with a finger that was still stained from work.\n\n\"Tell him,\" he said, \"to read this part.\"\n\nI translated, and the landlord read. His face turned slightly pink, and the fee disappeared from the conversation as quickly as it had arrived.\n\nAfter he left, my father squeezed my shoulder. \"You did not change my words,\" he said. \"Thank you.\"\n\nI realized then that he had never needed me to protect him from difficult information. He needed me to be accurate, so that he could protect himself.","questions":[{"type":"inference","q":"Why does the narrator hesitate when the landlord mentions a fee?","options":["She does not know the Vietnamese word for it.","She thinks her father already understood it.","She is tempted to make the news sound better."],"answer":2},{"type":"craft","q":"What does the comparison to \"carrying water from one bucket to another\" suggest?","options":["Translating is tiring work that she wants to avoid.","Translating usually means passing words along unchanged.","Translating often causes arguments in her family."],"answer":1},{"type":"literal","q":"What does the father bring to the table?","options":["a copy of the lease","a receipt for the heater","a letter from the bank"],"answer":0,"evidence":"Then he stood, walked to the drawer by the sink and returned with a folded copy of the lease."},{"type":"theme","q":"Which statement best expresses a theme of the story?","options":["Children should never be asked to help their parents.","Landlords usually take advantage of their tenants.","Respecting someone can mean telling them the full truth."],"answer":2}],"grade":7,"words":342,"auto":{"fk":5.3,"decodable":null,"checks":"pass"}},{"id":"pl-g7-02","pool":"placement-g7","title":"The Mantis Shrimp: Built to Strike and See","genre":"informational","source":"app-original","license":"app-original","text":"The mantis shrimp is not actually a shrimp. It belongs to a separate group of crustaceans called stomatopods, and most species live in burrows on warm, shallow sea floors. Although many are only a few inches long, the mantis shrimp has two features that have astonished scientists: a powerful strike and a remarkable set of eyes.\n\nSome mantis shrimp, known as smashers, have a pair of club-shaped limbs folded beneath their bodies. Each club works like a loaded spring. Muscles slowly store energy in a saddle-shaped structure, and a latch holds that energy in place. When the latch releases, the club snaps forward at about 50 miles per hour, one of the fastest movements of any animal. The blow can crack a snail's shell or a crab's armor in an instant.\n\nThe strike is so fast that it creates something unusual in the water. As the club moves, the water pressure around it drops so sharply that tiny bubbles form and then collapse. This process, called cavitation, releases a second burst of energy. Even if the club misses, the collapsing bubbles can stun its prey.\n\nWhy doesn't the club shatter? Researchers discovered that its inner layers are made of fibers stacked in a spiral pattern. When a crack starts, the spiral forces it to twist and spread out rather than travel straight through. Engineers are now studying this design to make tougher helmets and lighter materials for airplanes.\n\nThe eyes are just as strange. Each eye sits on a stalk and moves independently. Humans have three types of color receptors, but mantis shrimp have twelve or more. They can also detect forms of polarized light that are invisible to us. Surprisingly, experiments suggest they are not better than humans at telling similar colors apart. Instead, scientists think their eyes may help them recognize colors very quickly, without the complex processing that human brains perform.","questions":[{"type":"main","q":"What is the central idea of the passage?","options":["The mantis shrimp has an unusual strike and unusual eyes.","The mantis shrimp is a true shrimp that lives in deep water.","The mantis shrimp sees colors far better than any human."],"answer":0},{"type":"literal","q":"How fast can a smasher's club move?","options":["about 12 miles per hour","about 50 miles per hour","about 3 miles per hour"],"answer":1,"evidence":"When the latch releases, the club snaps forward at about 50 miles per hour, one of the fastest movements of any animal."},{"type":"why","q":"Why are engineers studying the mantis shrimp's club?","options":["Its spiral fibers keep cracks from spreading straight through.","Its saddle-shaped spring could power faster cars and boats.","Its tiny bubbles could be used to clean helmets and planes."],"answer":0},{"type":"author","q":"Why does the author describe the experiments on similar colors?","options":["To prove that mantis shrimp see no colors at all","To show that more receptors may not mean sharper vision","To explain how mantis shrimp detect polarized light"],"answer":1}],"grade":7,"words":316,"auto":{"fk":7.1,"decodable":null,"checks":"pass"}},{"id":"pl-g7-03","pool":"placement-g7","title":"Every Town Needs a Repair Café","genre":"argument","source":"app-original","license":"app-original","text":"When a toaster stops working, most people throw it away and buy a new one. It seems easier, and it is often cheaper. But this habit is filling landfills with machines that could have been saved by tightening a single loose wire. Every town should host a regular repair café, a free event where volunteers help neighbors fix broken things.\n\nThe idea began in Amsterdam in 2009, when a journalist named Martine Postma organized a gathering where people could bring damaged items and learn to repair them. Today there are thousands of repair cafés around the world. Volunteers with skills in electronics, sewing, carpentry and bicycles set up tables, and visitors bring lamps, jeans, chairs and laptops. The goal is not only to fix the object but also to show its owner how the repair was done.\n\nThe environmental case is strong. Electronic waste is one of the fastest-growing kinds of trash, and much of it contains materials that are difficult to recycle safely. Repairing a device keeps it in use and delays the need to manufacture a replacement.\n\nRepair cafés also strengthen communities. They bring together people who might never otherwise meet, such as a retired electrician, a teenager who understands phones and a parent who sews. Visitors often stay to talk long after their items are fixed.\n\nSome critics say that modern products are designed to be impossible to repair, so the effort is wasted. It is true that some devices are glued shut or require special tools. However, that is a reason to support repair, not to abandon it. Public pressure has already pushed several governments to pass \"right to repair\" laws that require companies to make parts and manuals available.\n\nA repair café costs very little to run. It needs a room, some tables and a few patient volunteers. In return, it saves money, reduces waste and reminds people that broken does not have to mean finished.","questions":[{"type":"claim","q":"What is the author's claim?","options":["Companies should stop making toasters.","Towns should hold regular repair cafés.","People should recycle all old devices."],"answer":1},{"type":"literal","q":"Who organized the first repair café?","options":["a journalist","an electrician","a carpenter"],"answer":0,"evidence":"The idea began in Amsterdam in 2009, when a journalist named Martine Postma organized a gathering where people could bring damaged items and learn to repair them."},{"type":"claim","q":"How does the author answer critics who say products cannot be repaired?","options":["By saying that all devices can be opened with simple tools","By saying that people should buy only older devices","By saying that this is a reason to push harder for repair"],"answer":2},{"type":"craft","q":"What does the final sentence of the passage suggest about broken objects?","options":["Broken items should be thrown away at once.","Damaged things can often have a longer life.","Repairs usually take a long time to finish."],"answer":1}],"grade":7,"words":322,"auto":{"fk":8.2,"decodable":null,"checks":"pass"}},{"id":"pl-g8-01","pool":"placement-g8","title":"The Audition","genre":"narrative","source":"app-original","license":"app-original","text":"The audition room at the conservatory was smaller than Lena had imagined, and much colder. Three judges sat behind a long table, their faces lit from below by the screens of their laptops. A single chair waited in the center of the floor, with a music stand beside it like a thin, patient guard.\n\nLena had practiced the Bach suite for eight months. She had played it in her bedroom, in the school auditorium and once, on a dare from her brother, on the platform of a subway station, where a man in a business suit had dropped a five-dollar bill into her open case and walked away without a word. She knew every note so well that she sometimes heard the music in her sleep.\n\nNow, sitting in the cold room, she could not remember how it began.\n\nHer fingers rested on the strings of the cello. Her bow hovered in the air. One of the judges, a woman with silver hair pulled into a tight knot, looked up from her screen and waited. The silence stretched until Lena could hear the radiator ticking in the corner.\n\nThen she remembered something her teacher had told her during their very first lesson: the music is not in your head; it is in your hands. Stop trying to remember it, and let your hands do what they have learned.\n\nLena closed her eyes and drew the bow across the lowest string. The first note filled the room, deep and warm, and the second followed it without being asked. By the time she opened her eyes again, she was halfway through the prelude, and the silver-haired judge had stopped looking at her screen entirely.","questions":[{"type":"why","q":"Why does Lena struggle at the start of her audition?","options":["Nervousness makes her forget how the piece begins.","Her cello has a broken string she cannot replace.","The judges ask her to play a different piece."],"answer":0},{"type":"craft","q":"What does describing the music stand as a \"thin, patient guard\" add to the scene?","options":["It makes the empty room feel tense and watchful.","It shows that the room is dangerous to enter.","It suggests the stand belongs to a security guard."],"answer":0},{"type":"vocab","q":"In the passage, what does \"hovered\" most nearly mean?","options":["stayed suspended in the air","fell suddenly to the floor","moved quickly back and forth"],"answer":0,"evidence":"Her bow hovered in the air."},{"type":"inference","q":"What does the judge's final reaction suggest?","options":["Lena's playing has captured the judge's full attention.","The judge has decided to end the audition early.","The judge is annoyed that Lena closed her eyes."],"answer":0}],"grade":8,"words":284,"auto":{"fk":6.7,"decodable":null,"checks":"pass"}},{"id":"pl-g8-02","pool":"placement-g8","title":"The Salamander That Regrows Itself","genre":"informational","source":"app-original","license":"app-original","text":"If a person loses a finger, the body seals the wound with scar tissue, and the finger is gone for good. If an axolotl loses an entire leg, something very different happens. Within a few weeks, a new leg grows in its place, complete with bones, muscles, nerves and skin. The new limb works just as well as the old one, and it leaves no scar.\n\nThe axolotl is a salamander found naturally in only one place on Earth: the system of lakes and canals around Xochimilco, near Mexico City. Unlike most salamanders, it never fully grows up. Even as an adult, it keeps features of a young larva, including feathery gills that stick out from the sides of its head like a frilly crown, and it spends its whole life in the water. Scientists call this trait neoteny.\n\nWhat has made the axolotl famous in laboratories, however, is its power of regeneration. It can rebuild not only limbs and tails but also parts of its spinal cord, heart, eyes and even brain. When a limb is lost, cells near the wound travel to the injury and form a small bump called a blastema. The cells in the blastema behave somewhat like the cells of a developing embryo. They divide rapidly and gradually organize themselves into the right tissues in the right places, so that a toe grows where a toe belongs.\n\nResearchers are still trying to learn exactly how this process works. In one well-known experiment, scientists removed certain immune cells called macrophages from axolotls. Without those cells, the animals formed scars and could no longer regrow their limbs. The result suggests that the immune system plays a key role in deciding whether a body heals by scarring or by rebuilding.\n\nScientists hope that understanding the axolotl could someday help doctors improve healing in people, such as after serious burns or spinal injuries. Ironically, the animal that might teach us so much is in danger. Pollution, invasive fish and the growth of Mexico City have shrunk its habitat, and wild axolotls are now critically endangered.","questions":[{"type":"main","q":"What is the central idea of the passage?","options":["Axolotls can regrow body parts, and scientists study how.","Axolotls are common salamanders found in most lakes.","Axolotls heal by forming thick scars, as humans do."],"answer":0},{"type":"vocab","q":"In the passage, what is a \"blastema\"?","options":["a feathery gill on the side of the head","a bump of cells that rebuilds a lost part","a kind of fish that eats young axolotls"],"answer":1,"evidence":"When a limb is lost, cells near the wound travel to the injury and form a small bump called a blastema."},{"type":"literal","q":"What happened to axolotls after their macrophages were removed?","options":["They grew two new legs in place of each lost one.","They regrew their lost limbs much faster than before.","They formed scars and could no longer regrow limbs."],"answer":2,"evidence":"Without those cells, the animals formed scars and could no longer regrow their limbs."},{"type":"author","q":"Why does the author call the axolotl's situation ironic?","options":["An animal that lives in water is a poor swimmer.","An animal that could help healing is itself at risk.","An animal that grows up quickly keeps its gills."],"answer":1}],"grade":8,"words":347,"auto":{"fk":8.9,"decodable":null,"checks":"pass"}},{"id":"pl-g8-03","pool":"placement-g8","title":"Let Everyone Make the Team","genre":"argument","source":"app-original","license":"app-original","text":"Every fall, dozens of students at large middle schools try out for teams with only fifteen or twenty spots. After a few days of drills, a list goes up on the gym door, and many hopeful players discover that their names are missing. For some, that moment ends their involvement in sports for good. Middle schools should adopt \"no-cut\" policies that let every student who commits to practice join a team.\n\nThe strongest reason is health. Regular exercise strengthens the heart, builds bones and improves mood, and national guidelines recommend that young people get an hour of physical activity every day. Yet surveys show that most teenagers fall short of that goal, and participation in organized sports often drops during adolescence. A student who is cut at age twelve may never try again.\n\nCutting players also misjudges talent. Middle school students grow and develop at very different rates. A short, uncoordinated seventh grader can become a strong athlete by tenth grade, but only if that student keeps playing. Coaches who cut players early are often rewarding students who simply matured first.\n\nCritics argue that no-cut teams are too large to coach well and that strong players need challenging competition. Those concerns can be addressed. Schools can create separate A and B teams, add extra practice groups or schedule more games against nearby schools, so that every player gets meaningful time. Competitive club teams and high school varsity teams will still exist for students who want them.\n\nMiddle school sports should be about building habits that last a lifetime, not about winning a trophy at fourteen. A no-cut policy keeps that door open.","questions":[{"type":"claim","q":"What is the author's claim?","options":["Middle schools should end all competitive games between schools.","Middle schools should cut more players so their teams win more.","Middle schools should let every committed student join a team."],"answer":2},{"type":"evidence","q":"Which sentence best supports the reason that early cuts misjudge talent?","options":["Coaches who cut players early are often rewarding students who simply matured first.","Competitive club teams and high school varsity teams will still exist for students who want them.","After a few days of drills, a list goes up on the gym door, and many hopeful players discover that their names are missing."],"answer":0,"evidence":"Coaches who cut players early are often rewarding students who simply matured first."},{"type":"claim","q":"Which counterclaim does the author address?","options":["Exercise does little to improve teen health.","Tryouts take too many days to complete.","No-cut teams are too large to coach well."],"answer":2},{"type":"author","q":"Why does the author describe the list on the gym door?","options":["To explain how coaches choose team captains","To show the disappointment that cuts cause","To describe where students find game schedules"],"answer":1}],"grade":8,"words":275,"auto":{"fk":8.2,"decodable":null,"checks":"pass"}},{"id":"pl-g9-01","pool":"placement-g9","title":"The Curve of Forgetting","genre":"informational","source":"app-original","license":"app-original","text":"In the 1880s, a German psychologist named Hermann Ebbinghaus set out to measure something that most people assumed could not be measured: the speed at which we forget. To avoid the influence of meaning, he invented thousands of nonsense syllables, such as \"DAX\" or \"BUP,\" which had no connection to anything he already knew. Then, serving as his own test subject, he memorized lists of these syllables and tested himself at intervals ranging from twenty minutes to a full month.\n\nThe results, published in 1885, were sobering. Ebbinghaus found that forgetting happened fastest right after learning. Within the first hour, he had lost a large portion of what he had memorized, and within a day, much more was gone. After that, the rate of forgetting slowed, and the small amount that remained tended to stay. When he plotted these results on a graph, they formed a steep downward slope that gradually flattened out. Psychologists still call this shape the forgetting curve.\n\nEbbinghaus also discovered something more encouraging. Each time he relearned a list, it took less effort than the time before, and the material faded more slowly afterward. Reviewing information at spaced intervals, rather than cramming it all at once, produced memories that lasted far longer. This finding, now known as the spacing effect, has been confirmed in hundreds of later studies involving everything from vocabulary words to medical procedures.\n\nThe lesson for students is surprisingly practical. Studying for three hours the night before a test may produce a decent score the next morning, but most of that knowledge will soon disappear. Spreading the same three hours across a week, with short reviews after one day, three days and a week, allows each review to catch a memory just as it begins to fade. Some modern flashcard apps are built around exactly this principle, scheduling each card to reappear shortly before the learner is likely to forget it.\n\nMore than a century after Ebbinghaus filled his notebooks with nonsense, his central insight remains one of the most useful ideas in the science of learning. Memory is not a recording that stays fixed once it is made. It is closer to a path through a field, which fades unless someone walks it again.","questions":[{"type":"main","q":"What is the central idea of the passage?","options":["Ebbinghaus proved that memory is fixed once it is formed.","Forgetting is fast, but spaced review makes memories last.","Nonsense syllables are the best way to learn a new language."],"answer":1},{"type":"why","q":"Why did Ebbinghaus use nonsense syllables in his experiments?","options":["so that meaning would not help him remember","so that his lists would be shorter to write","so that other people could not read his notes"],"answer":0},{"type":"vocab","q":"In paragraph 2, what does \"sobering\" most nearly mean?","options":["cheerful and exciting","confusing and unclear","serious and discouraging"],"answer":2,"evidence":"The results, published in 1885, were sobering."},{"type":"craft","q":"What does comparing memory to \"a path through a field\" suggest?","options":["Memories fade unless they are revisited.","Memories are stored in particular places.","Memories are clearest when we walk outside."],"answer":0}],"grade":9,"words":372,"auto":{"fk":9.3,"decodable":null,"checks":"pass"}},{"id":"pl-g9-02","pool":"placement-g9","title":"Energy Drinks Do Not Belong at School","genre":"argument","source":"app-original","license":"app-original","text":"Walk past a high school vending area or the trash cans outside a student parking lot, and you will see the same tall, brightly colored cans. Energy drinks have become a normal part of many teenagers' days. They should not be part of the school day. Schools should stop selling energy drinks and ban them from campus.\n\nThe main problem is caffeine. A single large can of some popular brands contains around 200 to 300 milligrams, roughly the amount in two or three cups of brewed coffee. Many students drink more than one can a day, often on top of soda or coffee. The American Academy of Pediatrics, an organization of children's doctors, has stated that energy drinks are not appropriate for children and teenagers. Doctors warn that heavy caffeine use can cause a racing heart, anxiety, upset stomachs and trouble sleeping.\n\nSleep is where the harm loops back into school. A student who drinks a large can at lunch may still feel its effects late at night. Poor sleep makes it harder to focus the next morning, which tempts the student to buy another can. The drink that promises energy can end up draining it.\n\nOther countries have already taken action. Since 2018, most large supermarkets in the United Kingdom have refused to sell energy drinks to customers under sixteen. If grocery stores can draw that line, schools, which are responsible for students' health during the day, can draw it too.\n\nSome people argue that teenagers should make their own choices and that banning a legal drink goes too far. Students can still buy energy drinks after school, and a ban will not change that. But a school is not a corner store. It already limits what it sells, keeping sugary sodas out of many cafeterias. Removing energy drinks from campus simply means that the school will not make an unhealthy habit easier.\n\nSchools exist to help students learn and grow. A drink that disrupts sleep and strains the heart does not fit that mission. The cans should go.","questions":[{"type":"claim","q":"What is the author's claim?","options":["Schools should ban energy drinks from campus.","Schools should sell energy drinks at lunch only.","Schools should replace coffee with energy drinks."],"answer":0},{"type":"evidence","q":"Which sentence best supports the claim that experts oppose energy drinks for teens?","options":["Many students drink more than one can a day, often on top of soda or coffee.","The American Academy of Pediatrics, an organization of children's doctors, has stated that energy drinks are not appropriate for children and teenagers.","A single large can of some popular brands contains around 200 to 300 milligrams, roughly the amount in two or three cups of brewed coffee."],"answer":1,"evidence":"The American Academy of Pediatrics, an organization of children's doctors, has stated that energy drinks are not appropriate for children and teenagers."},{"type":"claim","q":"How does the author respond to the counterclaim about personal choice?","options":["By saying teens should never drink caffeine anywhere.","By saying a school may limit what it sells on campus.","By saying stores should be forced to stop all sales."],"answer":1},{"type":"craft","q":"What does the phrase \"The drink that promises energy can end up draining it\" emphasize?","options":["The drinks taste worse than students expect.","The drinks cost more than other school snacks.","The drinks can cause the tiredness they claim to fix."],"answer":2}],"grade":9,"words":340,"auto":{"fk":6.5,"decodable":null,"checks":"pass"}},{"id":"pl-g9-03","pool":"placement-g9","title":"Nine Grams","genre":"narrative","source":"app-original","license":"app-original","text":"The mist nets went up before dawn, long and nearly invisible, strung between aluminum poles along the edge of the marsh like strands of fine black hair. By seven o'clock, Amara had already walked the net lanes twice with Dr. Okafor, the ornithologist who directed the banding station, checking carefully for any bird that had flown into the mesh. On the second round, they discovered a small yellow bird hanging motionless in the netting, as still and delicate as a leaf.\n\n\"Yellow warbler,\" Dr. Okafor said quietly. \"Go ahead. You've watched me do this every morning for a week.\"\n\nAmara's hands suddenly felt enormous and clumsy. She reminded herself of the sequence she had memorized: secure the legs first, then gently work the net away from the feet, the wings and finally the head, one strand at a time. The bird's heart fluttered against her fingertips, quick as rain on a window. When it finally came free, she held it in the bander's grip, its neck resting lightly between her first two fingers, exactly the way she had practiced with a stuffed toy at the station.\n\nBack at the banding table, she slipped a tiny aluminum band around the warbler's leg and closed it with specialized pliers. The band carried a number that no other bird in the world would ever wear. If a researcher recaptured this warbler someday, in Texas or Costa Rica or back in this same marsh the following spring, that number would reveal where it had traveled.\n\nShe measured the length of the wing, blew softly on the feathers of the belly to estimate how much fat the bird had stored for migration, and called out each measurement for Dr. Okafor to record. Then she lowered the warbler head-first into a small plastic tube resting on the digital scale.\n\n\"Nine point four grams,\" she announced.\n\nShe stared at the display in disbelief. Nine grams weighed less than two quarters, and yet this fragile creature would fly thousands of miles to Central America and back, guided by the stars and by an instinct that scientists still did not fully understand.\n\n\"Ready?\" Dr. Okafor asked.\n\nAmara carried the warbler to the edge of the table and slowly opened her hand. For half a second, it simply perched on her palm, weighing almost nothing at all. Then it vanished, a yellow streak disappearing into the willows.\n\nShe realized that she had been holding her breath, and she let it out gradually, smiling.","questions":[{"type":"literal","q":"What did Amara use to close the band around the bird's leg?","options":["specialized pliers","a plastic tube","a fine black net"],"answer":0,"evidence":"Back at the banding table, she slipped a tiny aluminum band around the warbler's leg and closed it with specialized pliers."},{"type":"inference","q":"What does Amara's reaction to the scale suggest?","options":["She thinks the scale must be broken.","She is amazed by what so small a bird can do.","She is worried that the bird is too thin to fly."],"answer":1},{"type":"craft","q":"What does the comparison \"quick as rain on a window\" help readers sense?","options":["the rapid, light heartbeat of the bird","the cold, wet weather at the marsh","the sound of the nets in the wind"],"answer":0},{"type":"theme","q":"Which theme does the story suggest?","options":["Careful work can bring a sense of wonder.","Wild animals should never be touched.","Science is mostly about writing down numbers."],"answer":0}],"grade":9,"words":414,"auto":{"fk":7.1,"decodable":null,"checks":"pass"}}];
